import fs from "node:fs";
import path from "node:path";

const dist = path.resolve("dist");
const distClient = path.resolve("dist/client");
const outputPublic = path.resolve(".output/public");

// Find whichever public directory was generated by the build
let primary = null;
if (fs.existsSync(dist) && fs.existsSync(path.join(dist, "about.html"))) {
  primary = dist;
} else if (fs.existsSync(outputPublic) && fs.existsSync(path.join(outputPublic, "about.html"))) {
  primary = outputPublic;
} else if (fs.existsSync(dist)) {
  primary = dist;
} else if (fs.existsSync(outputPublic)) {
  primary = outputPublic;
}

if (primary) {
  // 1. Ensure dist/client exists and has all static assets
  fs.mkdirSync(distClient, { recursive: true });
  for (const item of fs.readdirSync(primary)) {
    if (item === "client") continue;
    fs.cpSync(path.join(primary, item), path.join(distClient, item), { recursive: true });
  }

  // 2. Ensure .output/public exists and has all static assets
  if (primary !== outputPublic) {
    fs.mkdirSync(outputPublic, { recursive: true });
    for (const item of fs.readdirSync(primary)) {
      if (item === "client") continue;
      fs.cpSync(path.join(primary, item), path.join(outputPublic, item), { recursive: true });
    }
  }

  // 3. Ensure dist root has all static assets if primary was .output/public
  if (primary !== dist) {
    fs.mkdirSync(dist, { recursive: true });
    fs.cpSync(primary, dist, { recursive: true });
  }

  console.log(`[postbuild] Synced build artifacts across dist, dist/client, and .output/public`);
} else {
  console.warn(`[postbuild] No primary build output directory found to mirror`);
}
